using System.Text.Json;
using System.Reflection;

var root=Path.GetFullPath(args[0]);
if(!root.Replace('\\','/').EndsWith("/cs-review/fixture")) throw new Exception("Only an isolated cs-review/fixture directory is permitted.");
var json=new JsonSerializerOptions(JsonSerializerDefaults.Web);
var store=new SimRfqIntakeStore(root);
var r=(SimRfqIntakeRecord)(await store.ReadAsync("RFQI-SIM-0046"))!;
var p=r.OrderIntake!;var baseline=p.TechnicalSource!.Baseline!;
var docs=p.PoEvidence.Select(e=>e.Document).ToArray();
var actor=new SimPersona("cs-test","cs-test","C/S fixture reviewer","ACTIVE",[],[],true,"isolated test");
int count=0;void Check(bool b,string m){if(!b)throw new Exception(m);Console.WriteLine("PASS "+m);count++;}
var initial=SimCustomerSupply.Project(p);
var cs=initial.Lines.Where(l=>l.QuotedCustomerSupplied).ToArray();
Check(cs.Length==2 && cs.Single(l=>l.FindNumber=="1").RequiredQuantity==25,"Find 1 C/S minimum 25");
var six=cs.Single(l=>l.FindNumber=="6");
Check(six.CustomerPartNumber=="E8X001" && six.ApprovedPartNumber.Contains("B82801C565A100") && six.RequiredEach==2 && six.RequiredQuantity==50,"Find 6 identities and minimum 2 x 25 = 50");
Check(baseline.Materials.Rows.Single(l=>l.Quote.Index==5).Quote.OrderQuantity==25,"historical manual quote quantity remains 25");
Check(!initial.Lines.Single(l=>l.FindNumber=="7").QuotedCustomerSupplied,"customer PN, DLE-STK and zero cost do not infer C/S");
Check(!initial.Acknowledged,"no implicit acknowledgment");
var review=new SimCustomerSupplyReview(initial.SourceToken,cs.Select(l=>l.SourceRowId).ToArray(),true,"Reviewed against attached PO; no extra allowance.");
var reviewed=p with{CustomerSupplyReview=review};
Check(SimCustomerSupply.Project(reviewed).Acknowledged,"explicit matching review accepted");
Check(!SimCustomerSupply.Project(reviewed with{Facts=p.Facts with{Lines=[p.Facts.Lines[0] with{Quantity=26}]}}).Acknowledged,"quantity change invalidates acknowledgment");
Check(!SimCustomerSupply.Project(reviewed with{CustomerSupplyReview=review with{PoRowIds=[six.SourceRowId]}}).Acknowledged,"PO omitting quoted C/S remains unresolved");
Check(!SimCustomerSupply.Project(reviewed with{CustomerSupplyReview=review with{PoRowIds=initial.Lines.Select(l=>l.SourceRowId).ToArray()}}).Acknowledged,"extra PO C/S lines remain unresolved");
Check(!SimCustomerSupply.Project(baseline,p.Facts,p.PoNumber,[],review).Acknowledged,"attachment change invalidates acknowledgment");
Check(!SimCustomerSupply.Project(reviewed with{CustomerSupplyReview=review with{PoRowIds=["wrong-row"]}}).Acknowledged,"unknown source row rejected");
var bom=SimRfqIntakeStore.OrderEntryBom(reviewed);
Check(bom.Single(l=>l.Line=="6").CustomerSupply?.RequiredQuantity==50 && bom.Single(l=>l.Line=="7").CustomerSupply is null,"order-entry line-linked projection");
var row=baseline.Definition.Materials.Candidate.Rows.Single(l=>l.Index==5);
var group=JsonSerializer.SerializeToElement(SimKittingRequirementsProvider.ProjectGroup(row,25,"EA",six),json);
Check(group.GetProperty("customerSupply").GetProperty("customerPartNumber").GetString()=="E8X001" && group.GetProperty("requiredQuantity").GetDecimal()==50,"kitting C/S identity and quantity retained");
Check(group.GetProperty("entry").ValueKind==JsonValueKind.Null && group.GetProperty("rowState").GetString()=="EDITING","C/S acknowledgment creates no receipt or kit completion");
var legacy=JsonSerializer.SerializeToElement(SimKittingRequirementsProvider.ProjectGroup(row,25,"EA"),json);
Check(!legacy.TryGetProperty("customerSupply",out _) && legacy.GetProperty("notes").GetArrayLength()==0,"legacy released group shape unchanged");
Check(!JsonSerializer.Serialize(p,json).Contains("customerSupplyReview"),"legacy package hash shape omits null C/S field");
var metadata=JsonSerializer.Deserialize<SimStateMetadata>(File.ReadAllText(Path.Combine(root,"state","metadata.json")),json)!;
var request=new SimOrderSaveRequest(Guid.NewGuid().ToString(),r.RequestCorrelationId,r.IntakeId,p.Revision,r.Customer,p.PoNumber,p.Facts,p.PreviouslyQuoted,p.Quote!.Reference,p.Questionnaire,docs,p.WizardStep,false,p.TechnicalSource.Choice,[],p.WizardStepKey,p.PoFactsConfirmed==true,p.FlowVersion,false,null,p.PendingDueDateNote,review);
var saved=await store.SaveOrder(request,actor,metadata);
var reopened=(SimRfqIntakeRecord)(await new SimRfqIntakeStore(root).ReadAsync(r.IntakeId))!;
Check(reopened.OrderIntake!.CustomerSupplyReview==saved.Record.OrderIntake!.CustomerSupplyReview || JsonSerializer.Serialize(reopened.OrderIntake.CustomerSupplyReview,json)==JsonSerializer.Serialize(review,json),"C/S review survives actual draft save and new-store reopen");
Check(reopened.OrderEntry is null && reopened.Status=="DRAFT" && reopened.OrderIntake.PoEvidence.Length==docs.Length,"fixture save does not accept order or remove PO evidence");
var projection=await store.PreviewContractReview(request with{ExpectedRevision=reopened.OrderIntake.Revision},actor);
Check(projection.CustomerSupply!.Acknowledged && projection.Sections.Any(s=>s.Title==SimCustomerSupply.Label),"shared review renders acknowledged supply responsibility");
var blocker=typeof(SimRfqIntakeStore).GetMethod("OrderAcceptanceBlockers",BindingFlags.NonPublic|BindingFlags.Static)!;
var missingBlocks=(string[])blocker.Invoke(null,[p])!;
var reviewedBlocks=(string[])blocker.Invoke(null,[reviewed])!;
Check(missingBlocks.Any(x=>x.Contains("C/S")) && !reviewedBlocks.Any(x=>x.Contains("C/S")),"acceptance requires current explicit C/S review");
File.WriteAllText(Path.Combine(root,"cs-projection.json"),JsonSerializer.Serialize(projection,json));
Console.WriteLine($"PASS {count} C/S checks");

if(args.Length>1) await BuyerChecks.Run(root,args[1],six);
